INSERT INTO `hotel` (`id`, `name`, `location`, `address`, `description`, `image_url`, `price_per_night`, `created_at`) VALUES
  (1, 'Azure Bay Resort', 'Goa', '104 Calangute Beach Road, North Goa, 403516', 'A tranquil beachfront sanctuary offering panoramic Arabian Sea vistas, lush gardens, and direct private beach access.', NULL, 4500.00, '2026-11-13 21:25:01'),
  (2, 'Goa Palms Hideaway', 'Goa', '22 Vagator Cliff Path, Anjuna, Goa, 403509', 'An intimate boutique escape surrounded by swaying palms, designed for quiet retreats and sunset contemplation.', NULL, 2800.00, '2026-11-13 21:25:01'),
  (3, 'Marine Grand Suites', 'Mumbai', '78 Marine Drive, Nariman Point, Mumbai, 400021', 'A prestigious city haven facing the iconic Queen''s Necklace, tailored for modern urban travellers and business executives.', NULL, 6200.00, '2026-11-13 21:25:01'),
  (4, 'Heritage Haveli Palace', 'Jaipur', '15 Amber Fort Road, Pink City, Jaipur, 302001', 'A grand royal residence celebrating regal Rajasthani architecture, ornate courtyard fountains, and timeless hospitality.', NULL, 5100.00, '2026-11-13 21:25:01'),
  (5, 'Silicon Heights Inn', 'Bengaluru', '45 Indiranagar 100ft Road, Bengaluru, 560038', 'A contemporary and vibrant tech-district hub with ergonomic modern spaces, curated local art, and artisan caf├® dining.', NULL, 3700.00, '2026-11-13 21:25:01');
